import { rng } from '../../lib/random';

/** A cell of an explicit complex: its boundary is the sum of `coeff · faces[i].cell`. */
export interface Cell {
  label: string;
  dim: number;
  faces: { cell: number; coeff: number }[];
  /** The filtration value, or null to take the largest of its faces' values. */
  value: number | null;
  /** A position in the plane (vertices only), for drawing. */
  pos?: [number, number];
}

export type Complex = Cell[];

// ---- Simplicial complexes ----

/**
 * The simplicial complex generated by `simplices` (lists of vertex numbers), with every face, oriented boundaries
 * (∂[v0 … vk] = Σ (−1)^i [v0 … v̂i … vk]) and cells listed by dimension.
 */
export function simplicial(
  simplices: number[][],
  opts: {
    names?: string[];
    positions?: [number, number][];
    value?: (vertices: number[]) => number | null;
  } = {},
): Complex {
  const key = (s: number[]) => s.join(',');
  const all = new Map<string, number[]>();
  const add = (s: number[]) => {
    if (all.has(key(s))) return;
    all.set(key(s), s);
    if (s.length > 1) s.forEach((_, i) => add(s.filter((_, j) => j !== i)));
  };
  simplices.forEach((s) => add([...new Set(s)].sort((a, b) => a - b)));
  const list = [...all.values()].sort((a, b) => a.length - b.length || key(a).localeCompare(key(b), undefined, { numeric: true }));
  const index = new Map(list.map((s, i) => [key(s), i]));
  const name = (v: number) => opts.names?.[v] ?? String(v);
  const separator = list.some((s) => s.length === 1 && name(s[0]).length > 1) ? '-' : '';
  return list.map((s) => ({
    label: s.map(name).join(separator),
    dim: s.length - 1,
    faces: s.length > 1 ? s.map((_, i) => ({ cell: index.get(key(s.filter((_, j) => j !== i)))!, coeff: i % 2 === 0 ? 1 : -1 })) : [],
    value: opts.value ? opts.value(s) : null,
    pos: s.length === 1 ? opts.positions?.[s[0]] : undefined,
  }));
}

/** The vertices of every cell (assuming it is built from vertices up). */
export function vertexSets(c: Complex): number[][] {
  const out: number[][] = [];
  c.forEach((cell, i) => {
    if (cell.dim === 0 || cell.faces.length === 0) out[i] = [i];
    else out[i] = [...new Set(cell.faces.flatMap((f) => out[f.cell] ?? []))].sort((a, b) => a - b);
  });
  return out;
}

/** Every cell's value, filling in missing ones with the largest of the faces' (as phlite does). */
export function effectiveValues(c: Complex): number[] {
  const out: number[] = [];
  const order = c.map((_, i) => i).sort((a, b) => c[a].dim - c[b].dim);
  for (const i of order) {
    const v = c[i].value;
    out[i] = v ?? (c[i].faces.length ? Math.max(...c[i].faces.map((f) => out[f.cell] ?? 0)) : 0);
  }
  return out;
}

/** Whether the complex can be drawn in the plane: every vertex has a position, and nothing is above dimension 2. */
export function drawable(c: Complex): boolean {
  return c.length > 0 && c.every((cell) => cell.dim <= 2 && (cell.dim > 0 || cell.pos !== undefined));
}

// ---- Examples ----

const RUNNING: [string, number, number[], number][] = [
  ['a', 0, [], 0], ['b', 0, [], 0], ['c', 0, [], 1], ['ab', 1, [0, 1], 1], ['bc', 1, [1, 2], 1], ['ac', 1, [0, 2], 2],
  ['d', 0, [], 2], ['cd', 1, [2, 6], 3], ['bd', 1, [1, 6], 3], ['abc', 2, [3, 4, 5], 4],
];

/** A triangulated torus or Klein bottle: an n × n grid of squares, each cut in two, with opposite sides glued. */
function gluedGrid(n: number, twist: boolean): Complex {
  const v = (i: number, j: number) => {
    // Going once round in j flips i (for the Klein bottle)
    const wraps = Math.floor(j / n);
    let ii = ((i % n) + n) % n;
    if (twist && wraps % 2 !== 0) ii = (n - ii) % n;
    return ii * n + (((j % n) + n) % n);
  };
  const triangles: number[][] = [];
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++) {
      triangles.push([v(i, j), v(i + 1, j), v(i + 1, j + 1)]);
      triangles.push([v(i, j), v(i, j + 1), v(i + 1, j + 1)]);
    }
  return simplicial(triangles, { value: () => 0 });
}

export interface ComplexExample {
  id: string;
  name: string;
  about: string;
  modulus: number;
  make: () => Complex;
}

export const EXAMPLES: ComplexExample[] = [
  {
    id: 'running',
    name: "The book's running example",
    about: 'Ten cells: two triangles\' worth of edges, one triangle filled in. Bars: three H₀ (one essential), two H₁ (one dies when abc fills it, one never does).',
    modulus: 2,
    make: () => {
      const pos: Record<string, [number, number]> = { a: [0, 0], b: [1, 0], c: [0.5, 0.85], d: [1.55, 0.95] };
      return RUNNING.map(([label, dim, faces, value]) => ({
        label,
        dim,
        // Oriented so that it works over any field: ∂(xy) = y − x, ∂(abc) = bc − ac + ab
        faces: faces.map((f, i) => ({ cell: f, coeff: dim === 1 ? (i === 0 ? -1 : 1) : [1, 1, -1][i] })),
        value,
        pos: dim === 0 ? pos[label] : undefined,
      }));
    },
  },
  {
    id: 'sphere',
    name: 'Sphere',
    about: 'The boundary of a tetrahedron. Every cell enters at 0, so only the essential bars are left: the Betti numbers, 1, 0, 1.',
    modulus: 2,
    make: () => simplicial([[0, 1, 2], [0, 1, 3], [0, 2, 3], [1, 2, 3]], { value: () => 0 }),
  },
  {
    id: 'torus',
    name: 'Torus',
    about: 'A 3 × 3 grid glued into a torus (9 vertices, 27 edges, 18 triangles), every cell at 0: Betti numbers 1, 2, 1, over any field.',
    modulus: 2,
    make: () => gluedGrid(3, false),
  },
  {
    id: 'rp2',
    name: 'Projective plane',
    about:
      'The 6-vertex projective plane, every cell at 0. Over Z/2 it has H₁ and H₂ of rank 1; over Z/3 (try it in Compute) both vanish: its H₁ is Z/2 over the integers, which only fields of characteristic 2 see.',
    modulus: 2,
    make: () =>
      simplicial(
        [[1, 2, 4], [1, 2, 6], [1, 3, 5], [1, 3, 6], [1, 4, 5], [2, 3, 4], [2, 3, 5], [2, 5, 6], [3, 4, 6], [4, 5, 6]].map((t) => t.map((v) => v - 1)),
        { value: () => 0 },
      ),
  },
  {
    id: 'klein',
    name: 'Klein bottle',
    about: 'A 4 × 4 grid glued with a twist, every cell at 0. Over Z/2: Betti numbers 1, 2, 1. Over Z/3: 1, 1, 0 (it isn\'t orientable).',
    modulus: 2,
    make: () => gluedGrid(4, true),
  },
];

/** A random geometric complex: points in the square, edges between points closer than `radius`, and every triangle. */
export function randomComplex(n: number, radius: number, values: 'rips' | 'height', seed: number): Complex {
  const r = rng(seed);
  const pts: [number, number][] = Array.from({ length: n }, () => [r.next(), r.next()]);
  const heights = pts.map(() => r.next());
  const d = (a: number, b: number) => Math.hypot(pts[a][0] - pts[b][0], pts[a][1] - pts[b][1]);
  const close = (a: number, b: number) => d(a, b) <= radius;
  const simplices: number[][] = pts.map((_, i) => [i]);
  for (let a = 0; a < n; a++)
    for (let b = a + 1; b < n; b++) {
      if (!close(a, b)) continue;
      simplices.push([a, b]);
      for (let c = b + 1; c < n; c++) if (close(a, c) && close(b, c)) simplices.push([a, b, c]);
    }
  return simplicial(simplices, {
    positions: pts,
    value: (s) => {
      if (values === 'height') return s.length === 1 ? Math.round(100 * heights[s[0]]) / 100 : null;
      let m = 0;
      for (const a of s) for (const b of s) m = Math.max(m, d(a, b));
      return Math.round(1000 * m) / 1000;
    },
  });
}

// ---- The text format ----

export const FORMAT_HELP = `One cell per line: label, dimension, value, then its faces after a colon.
The value can be _ to take the largest of its faces' values. A vertex can have a position, @ x y.
A face can carry a coefficient: 2*ab, or -ab for −1. Lines starting with # are comments.`;

export function toText(c: Complex): string {
  const lines = ['# label dim value [@ x y] [: faces]'];
  for (const cell of c) {
    let line = `${cell.label} ${cell.dim} ${cell.value ?? '_'}`;
    if (cell.pos) line += ` @ ${+cell.pos[0].toFixed(4)} ${+cell.pos[1].toFixed(4)}`;
    if (cell.faces.length)
      line +=
        ' : ' +
        cell.faces
          .map(({ cell: f, coeff }) => `${coeff === 1 ? '' : coeff === -1 ? '-' : `${coeff}*`}${c[f].label}`)
          .join(' ');
    lines.push(line);
  }
  return lines.join('\n');
}

export function parseText(text: string): Complex {
  const cells: Complex = [];
  const byLabel = new Map<string, number>();
  text.split(/\r?\n/).forEach((raw, i) => {
    const line = raw.replace(/#.*/, '').trim();
    if (!line) return;
    const where = `Line ${i + 1}`;
    const [head, facesPart] = line.split(':');
    const [main, posPart] = head.split('@');
    const parts = main.trim().split(/\s+/);
    if (parts.length !== 3) throw new Error(`${where}: expected "label dim value", got "${main.trim()}"`);
    const [label, dimText, valueText] = parts;
    if (byLabel.has(label)) throw new Error(`${where}: the label "${label}" is used twice`);
    const dim = Number(dimText);
    if (!Number.isInteger(dim) || dim < 0) throw new Error(`${where}: the dimension "${dimText}" isn't a non-negative integer`);
    const value = valueText === '_' ? null : Number(valueText);
    if (value !== null && !Number.isFinite(value)) throw new Error(`${where}: the value "${valueText}" isn't a number (or _)`);
    let pos: [number, number] | undefined;
    if (posPart !== undefined) {
      const xy = posPart.trim().split(/\s+/).map(Number);
      if (xy.length !== 2 || xy.some((x) => !Number.isFinite(x))) throw new Error(`${where}: expected "@ x y"`);
      pos = [xy[0], xy[1]];
    }
    const faces = (facesPart ?? '')
      .trim()
      .split(/\s+/)
      .filter(Boolean)
      .map((token) => {
        const m = token.match(/^([+-]?)(?:(\d+)\*)?(.+)$/)!;
        const coeff = (m[1] === '-' ? -1 : 1) * (m[2] ? Number(m[2]) : 1);
        const face = byLabel.get(m[3]);
        if (face === undefined) throw new Error(`${where}: the face "${m[3]}" isn't defined (faces must come first)`);
        if (cells[face].dim !== dim - 1) throw new Error(`${where}: "${m[3]}" has dimension ${cells[face].dim}, not ${dim - 1}`);
        return { cell: face, coeff };
      });
    byLabel.set(label, cells.length);
    cells.push({ label, dim, faces, value, pos });
  });
  if (cells.length === 0) throw new Error('No cells');
  return cells;
}
